package com.bank.lenhist;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class CountByLengthDemo {
    private static final Logger log = Logger.getLogger("LenHist");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> codes = List.of("SAV2001", "ACC10", "CUR3001", "TXN90", "A");
        LengthHistogramService service = new LengthHistogramService();

        Map<Integer, Long> hist = service.countByLength(codes);
        log.info(() -> "Length histogram: " + hist);
    }
}

// ─── Would be in service/LengthHistogramService.java ───
class LengthHistogramService {
    Map<Integer, Long> countByLength(List<String> codes) {
        return codes.stream()
            .filter(Objects::nonNull)
            .collect(groupingBy(
                String::length,         // classifier: length
                TreeMap::new,           // sorted keys
                counting()));           // count per length (Long)
    }
}
